import {useClickAnalytics} from '@github-ui/use-analytics'
import {useMemo} from 'react'

const ANALYTICS_CATEGORY = 'Global navigation'

export function useGlobalNavAnalytics(appName?: string) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  return useMemo(() => {
    return {
      sendItemClick: (action: string) => {
        sendClickAnalyticsEvent({
          app_name: appName,
          category: ANALYTICS_CATEGORY,
          action,
        })
      },
    }
  }, [sendClickAnalyticsEvent, appName])
}
