type ConfigKeys = (typeof GlobalMenuItems)[number][number]['key']

type WithShow<T> = T & {
  /** Enables overriding the default to hide/show the menu-item on selective configurations */
  show?: boolean
}

type NavMenuOverrides = Partial<Record<ConfigKeys, Partial<WithShow<Pick<GlobalNavMenuItem, 'href' | 'hotkey'>>>>>

export type GlobalNavMenuProps = NavMenuOverrides & {
  /**
   * If the menu is currently open or not
   * Even when the menu is closed, this is required to support user hot-keys for menu items behind the drawer.
   * @default true
   */
  open?: boolean

  richContent?: {
    /**
     * Enables the display of rich content in the navigation menu.
     * This is used to display dynamic content such as repositories and teams.
     *
     * @default false
     */
    enabled?: boolean

    /**
     * The location to pull the initial config for rich content from.
     * These endpoints should return the initial data required to populate teams & repositories.
     * If `richContentEnabled` is false or not provided, these URLs will be ignored.
     */
    contentUrl?: string

    repositoriesSearchUrl?: string
    teamsSearchUrl?: string
  }
} & Pick<DialogProps, 'onClose' | 'returnFocusRef'>

/**
 * The main navigation menu component for the application.
 * It renders a side navigation menu with support for rich content.
 *
 * Handling for specific menu-items can be controlled via the individual props:
 * i.e.
 * ```tsx
 * <GlobalNavMenu
 *   home={{ show: true, href: '/custom-home', hotkey: 'h' }}
 *   issues={{ show: false }}
 * />
 * ```
 *
 */
export function GlobalNavMenu(props: GlobalNavMenuProps) {
  const {open = true, onClose, richContent} = props

  const [mainGroup, secondaryGroup] = GlobalMenuItems.map(group => {
    return group
      .filter(item => {
        if (props[item.key]?.show !== undefined) {
          return props[item.key]?.show
        }

        return item.show !== false
      })
      .map(({show: _show, ...item}) => {
        const {show, ...overrides} = props[item.key] ?? {}

        return {
          ...item,
          ...overrides,
        }
      })
  })

  if (!open) {
    // If the menu is not open, we don't render anything visually.
    // However, we still render the nav-items that have hot-keys assigned to them, otherwise nothing will listen for the events
    return <GlobalNavHotKeys menuItems={[...(mainGroup ?? []), ...(secondaryGroup ?? [])]} />
  }

  return (
    <SideNavMenu onClose={onClose}>
      <NavList.Group>
        {mainGroup?.map(({key, ...item}) => {
          return (
            <SideNavMenuItem
              key={key}
              className={clsx({
                // Hide the copilot button on stationary and re-show in it's own group
                'hide-whenNarrow':
                  (key === 'copilot' || key === 'spark') && isFeatureEnabled('global_nav_copilot_a11y_fix'),
              })}
              {...item}
            />
          )
        })}
      </NavList.Group>

      {/*
        TODO: Fix as part of https://github.com/github/global-navigation/issues/127

        These links are only shown on mobile viewports as a workaround for an accessibility issue:
        https://github.com/github/accessibility-audits/issues/11848

        This should be relatively short lived, as this side panel is scheduled to be rewritten in React.
      */}
      {props.copilot?.show && isFeatureEnabled('global_nav_copilot_a11y_fix') && (
        <>
          {/* Using an ActionList here to avoid the NavList.Group auto-adding a divider when not shown */}
          <ActionList.Divider className="show-whenNarrow" />
          <ActionList.Group className="show-whenNarrow">
            {mainGroup?.map(({key, ...item}) => {
              if (key === 'copilot' || key === 'spark') {
                return <SideNavMenuItem key={key} {...item} />
              }

              return null
            })}
            <CopilotMenuItems />
          </ActionList.Group>
        </>
      )}

      {(secondaryGroup?.length ?? 0) > 0 && (
        <NavList.Group>
          {secondaryGroup?.map(({key, ...item}) => {
            return <SideNavMenuItem key={key} {...item} />
          })}
        </NavList.Group>
      )}
      {richContent?.enabled && richContent.contentUrl && (
        <DynamicSidePanelContent
          richContentUrl={richContent.contentUrl}
          repositoriesSearchUrl={richContent.repositoriesSearchUrl}
          teamsSearchUrl={richContent.teamsSearchUrl}
        />
      )}
    </SideNavMenu>
  )
}

/**
 * Renders a hidden version of the GlobalNavMenu to support user hot-keys for any menu-item that has it enabled.
 * This component does not render anything visual, and should be used when the menu is collapsed
 */
export function GlobalNavHotKeys(props: {menuItems: GlobalNavMenuItem[]}) {
  return (
    <div className="d-none">
      {props.menuItems.map(({key, ...item}) => {
        if (!item.hotkey) {
          return null
        }

        return <SideNavMenuItem key={key} {...item} />
      })}
    </div>
  )
}

export function ExternallyAnchoredGlobalNavMenu(
  props: Omit<GlobalNavMenuProps, 'onClose' | 'anchorRef'> & Required<ReactPartialAnchorProps>,
) {
  const {ref: anchorRef, open, setOpen} = useExternalAnchor(props.reactPartialAnchor)

  const onClose = useCallback(() => {
    setOpen(false)
  }, [setOpen])

  return <GlobalNavMenu returnFocusRef={anchorRef} open={open} onClose={onClose} {...props} />
}

export interface InternallyAnchoredGlobalNavMenuProps extends Omit<GlobalNavMenuProps, 'onClose'> {
  /**
   * The initial state of the menu on the first render before being controlled
   */
  initialMenuOpen?: boolean
}

export function InternallyAnchoredGlobalNavMenu(props: InternallyAnchoredGlobalNavMenuProps) {
  const [open, setOpen] = useState(props.initialMenuOpen ?? false)
  const anchorRef = useRef<HTMLButtonElement>(null)

  const onClose = useCallback(() => {
    setOpen(false)
  }, [setOpen])

  return (
    <>
      <IconButton aria-haspopup="dialog" onClick={() => setOpen(!open)} aria-label="Open Menu" icon={ThreeBarsIcon} />
      {<GlobalNavMenu returnFocusRef={anchorRef} open={open} onClose={onClose} {...props} />}
    </>
  )
}

export function GlobalNavMenuPartial(props: GlobalNavMenuProps & ReactPartialAnchorProps) {
  if (props.reactPartialAnchor) {
    return <ExternallyAnchoredGlobalNavMenu reactPartialAnchor={props.reactPartialAnchor} {...props} />
  }

  return <InternallyAnchoredGlobalNavMenu {...props} />
}

export type GlobalNavMenuItem = SideNavMenuItemProps & {
  /** The config key to use when overriding props */
  key: string
}

